  'Research Methods in Political Science',
  'Frame political science as systematic inquiry into power, institutions, behavior, policy, conflict, representation, and governance. Topics cover theory and hypotheses, research design and causal logic, measurement, data sources and reproducible workflow, case studies, process tracing, interviews and fieldwork, surveys, experiments, regression, content analysis and text-as-data, mixed methods, ethics and open science, and a research proposal or replication portfolio.',
  $rmpsjson${"slug": "research-methods-in-political-science", "title": "Research Methods in Political Science", "description": "Frame political science as systematic inquiry into power, institutions, behavior, policy, conflict, representation, and governance. Topics cover theory and hypotheses, research design and causal logic, measurement, data sources and reproducible workflow, case studies, process tracing, interviews and fieldwork, surveys, experiments, regression, content analysis and text-as-data, mixed methods, ethics and open science, and a research proposal or replication portfolio.", "topics": [{"id": "195370ec-163a-41b0-9e74-5a730ddc6b7f", "type": "topic", "title": "Political Science Inquiry, Research Questions, and Scientific Method", "description": "Frame political science as systematic inquiry into power, institutions, behavior, policy, conflict, representation, and governance.", "children": [{"id": "ffaf2dc0-0974-4b77-b15f-57bc91a63be1", "type": "subtopic", "title": "What political scientists study", "children": [{"id": "b4abf534-d670-4b0a-86ae-78f093fc6aa1", "type": "concept", "title": "Power and authority"}, {"id": "fd0b4bed-a426-4a21-bd81-65474d9911e6", "type": "concept", "title": "Institutions"}, {"id": "460f06ac-51b3-4477-8f15-d08d73696434", "type": "concept", "title": "Political behavior"}, {"id": "ab2139a6-d10f-4db1-8410-6d76fef8e0bd", "type": "concept", "title": "Policy and conflict"}], "description": "Students begin by seeing research methods as tools for understanding real political questions."}, {"id": "3942b72f-23c7-43c1-9ae8-3831e7611d0a", "type": "subtopic", "title": "Researchable questions", "children": [{"id": "b0955516-512d-4598-8327-cd6b25d0c385", "type": "concept", "title": "Descriptive questions"}, {"id": "f56cc7f1-9df0-4a62-8484-6a6f266e16b5", "type": "concept", "title": "Causal questions"}, {"id": "fc3ee0ac-6e3d-4876-8b50-2c2b12b1697a", "type": "concept", "title": "Normative vs empirical questions"}, {"id": "d6e82dd8-1027-4a92-a91f-a769a2beaacb", "type": "concept", "title": "Scope conditions"}], "description": "Good research questions are specific, important, answerable, and connected to evidence."}, {"id": "d957154a-53b6-4705-b75f-67c283994a26", "type": "subtopic", "title": "Scientific method in political science", "children": [{"id": "845e493c-9367-4840-ad09-fe1eb096a49a", "type": "concept", "title": "Observation"}, {"id": "b0b739cb-dca2-4d69-ab21-3195482a4428", "type": "concept", "title": "Theory"}, {"id": "ce1d513a-9ae6-4097-926e-2aa49beeabf1", "type": "concept", "title": "Hypothesis"}, {"id": "7a2f1258-2493-481b-b361-b583008332d5", "type": "concept", "title": "Evidence and revision"}], "description": "The scientific method makes political arguments testable, transparent, and open to revision."}]}, {"id": "3867a9f9-2a1c-4d0a-a0fb-d589442460a5", "type": "topic", "title": "Theory, Concepts, Hypotheses, and Literature Reviews", "description": "Turn broad political questions into theory-driven concepts, testable claims, and researchable scholarly conversations.", "children": [{"id": "98d54fe2-6796-4123-ad8f-88daa033d28e", "type": "subtopic", "title": "Theory building", "children": [{"id": "1603efc3-9987-42f3-8129-edd232f903aa", "type": "concept", "title": "Actors and incentives"}, {"id": "3d48790c-003c-4225-a139-6fb83ae92db1", "type": "concept", "title": "Institutions and constraints"}, {"id": "44112254-7746-4f13-8315-8908a26a04f2", "type": "concept", "title": "Mechanisms"}, {"id": "247123fa-f04d-4ff0-9df5-85eb0afe2e6d", "type": "concept", "title": "Alternative explanations"}], "description": "Theory explains why political outcomes happen and what mechanisms connect causes to effects."}, {"id": "537c0a12-6f5f-4a15-8857-7614d60e45a7", "type": "subtopic", "title": "Concepts and hypotheses", "children": [{"id": "e3281742-e6eb-44a8-a9a7-34978d4684e1", "type": "concept", "title": "Conceptual definition"}, {"id": "59eac934-fc2e-4b4a-b7a1-6172219a4671", "type": "concept", "title": "Hypotheses"}, {"id": "3cabc724-8c36-46ff-9757-fed28fc2bccc", "type": "concept", "title": "Independent and dependent variables"}, {"id": "1d326c9e-c1b4-47c9-bbb3-c13ee8cebe93", "type": "concept", "title": "Observable implications"}], "description": "Conceptual clarity prevents students from testing vague ideas with mismatched evidence."}, {"id": "293e8ebd-2313-43ae-87f7-4b558de6953f", "type": "subtopic", "title": "Literature review", "children": [{"id": "15a9644a-775b-427f-b0ca-9804a529e8b3", "type": "concept", "title": "Research gap"}, {"id": "dde81de6-753c-4dd2-ae63-f7b397f83caa", "type": "concept", "title": "Schools of thought"}, {"id": "c5ab0e7e-db19-49fe-a2c0-1ef3d3575c7f", "type": "concept", "title": "Citation tracing"}, {"id": "fcfdf384-d822-47ff-b2d5-3e0a03a5044b", "type": "concept", "title": "Synthesis rather than summary"}], "description": "A literature review positions a project inside an ongoing scholarly debate rather than a loose collection of sources."}]}, {"id": "652ecd6e-34a9-4d39-b939-a2593396ca7d", "type": "topic", "title": "Research Design, Causal Logic, and Inference", "description": "Learn how design choices support valid descriptive and causal claims about political phenomena.", "children": [{"id": "dbc7ca6c-b46a-4e52-a228-868d0b7d2222", "type": "subtopic", "title": "Research design logic", "children": [{"id": "190d4c8c-8866-4df7-b91e-78e868a22d08", "type": "concept", "title": "Units of analysis"}, {"id": "cfdc405c-cffb-4f52-9942-38fde80e34b7", "type": "concept", "title": "Population and sample"}, {"id": "4557b7f5-f4ed-4bbc-9ad5-a11230df998f", "type": "concept", "title": "Comparison"}, {"id": "e79dab3a-229e-41e1-935c-db1e9b210c7b", "type": "concept", "title": "Research design tradeoffs"}], "description": "Design choices determine what kind of claim a study can credibly make."}, {"id": "7d8033fa-2da8-4de3-9cb0-340c08411b71", "type": "subtopic", "title": "Causal inference fundamentals", "children": [{"id": "c202d67f-2dea-4845-870c-6a822be3a5e6", "type": "concept", "title": "Counterfactuals"}, {"id": "899960f0-4c94-428d-ae11-2247b2c10bb9", "type": "concept", "title": "Treatment and outcome"}, {"id": "01cd3134-c166-4291-b1d0-8af975637711", "type": "concept", "title": "Confounding"}, {"id": "bdb9c7f3-eb34-44bd-9189-77756fc80f94", "type": "concept", "title": "Internal and external validity"}], "description": "Causal inference asks what would have happened under a different political condition."}, {"id": "fd10b483-fc8a-42aa-9063-847448125ba0", "type": "subtopic", "title": "Threats to inference", "children": [{"id": "c036b2dd-f2e3-4622-926f-209295393b38", "type": "concept", "title": "Selection bias"}, {"id": "778d58b9-f3a9-4314-9c14-ecdbc3991291", "type": "concept", "title": "Omitted variables"}, {"id": "72008812-6a6e-4e4f-93d8-5a8dfc3bc114", "type": "concept", "title": "Reverse causality"}, {"id": "a7c659af-e3dd-47ea-9e56-fe3db3404076", "type": "concept", "title": "Measurement bias"}], "description": "Students learn to diagnose the weaknesses that make findings less credible."}]}, {"id": "9c2e56ea-dc76-4a9c-81b7-89a70f8c7087", "type": "topic", "title": "Measurement, Operationalization, Data Quality, and Validity", "description": "Connect abstract political concepts to observable indicators while managing measurement error and validity threats.", "children": [{"id": "bbac1a14-f74e-4403-8c17-be09c20d45b8", "type": "subtopic", "title": "Operationalization", "children": [{"id": "e80088e6-1b7d-43a3-8635-6af0ad4d5b5b", "type": "concept", "title": "Indicators"}, {"id": "caaf602a-2f53-4408-b02b-f18c7c748a0b", "type": "concept", "title": "Scales and indexes"}, {"id": "adef6045-6869-486d-87df-8cb716c98510", "type": "concept", "title": "Coding rules"}, {"id": "585f570e-53b4-4404-b9a0-2fadae603b7c", "type": "concept", "title": "Proxy measures"}], "description": "Operationalization turns concepts like democracy, polarization, turnout, or corruption into measurable indicators."}, {"id": "d5e09f97-e638-4e45-8041-885116b84c4d", "type": "subtopic", "title": "Reliability and validity", "children": [{"id": "0a86c7b4-18e2-46a2-bb16-6f8670529688", "type": "concept", "title": "Reliability"}, {"id": "48c28a78-44e6-4312-a916-6e0cfb27cf01", "type": "concept", "title": "Construct validity"}, {"id": "2c3ab8de-26c3-4688-a7fc-00e0ca79db63", "type": "concept", "title": "Content validity"}, {"id": "6debb4b2-d244-40e7-9182-82907726ccbc", "type": "concept", "title": "Criterion validity"}], "description": "Measures must be consistent and actually capture the concept they claim to represent."}, {"id": "77a2b106-f73c-4e93-8d9d-59be61de928e", "type": "subtopic", "title": "Data quality", "children": [{"id": "26edcced-55c2-4182-9c6d-89e4501573e2", "type": "concept", "title": "Missing data"}, {"id": "383ab4c4-0303-47ed-bb15-00cc4f4f784c", "type": "concept", "title": "Outliers"}, {"id": "3e46ba61-adda-437a-b9fb-41f5c4b680a2", "type": "concept", "title": "Data provenance"}, {"id": "b27a81f5-6219-4551-900e-52e186706060", "type": "concept", "title": "Measurement error"}], "description": "Political data often contain missingness, bias, uncertainty, and strategic reporting."}]}, {"id": "5795fe18-f0e8-459a-b913-f1ca5afda7fa", "type": "topic", "title": "Data Sources for Political Science and Reproducible Workflow", "description": "Use political datasets, archives, code, documentation, version control, and transparent workflows to make research credible.", "children": [{"id": "f2d8de2a-3572-49b5-8daf-a0282ade3ca1", "type": "subtopic", "title": "Political science datasets", "children": [{"id": "cd109a2f-18ca-4ce6-81c2-e1f26335b6ca", "type": "concept", "title": "ICPSR"}, {"id": "7476f0e9-160a-4df1-ae07-36b1b4b70ef9", "type": "concept", "title": "ANES"}, {"id": "c643ac6a-1b58-4703-bdac-1ef74b28ffec", "type": "concept", "title": "V-Dem"}, {"id": "64703614-25d1-405d-9e9c-f78256ca3077", "type": "concept", "title": "World Bank and QoG data"}], "description": "Students learn where political data come from and how dataset choices shape findings."}, {"id": "f9a5df5a-683e-4f6b-a17c-50c524e88da8", "type": "subtopic", "title": "Reproducible workflow", "children": [{"id": "ab6370f9-4a81-409e-86f6-bb70dc1d20a9", "type": "concept", "title": "Project folders"}, {"id": "b26e540f-079e-4232-b3c1-6ad6e47b70b1", "type": "concept", "title": "Code notebooks"}, {"id": "f5601d61-a679-448f-ac2b-c205e21fa796", "type": "concept", "title": "Version control"}, {"id": "99551ed3-95e9-4413-9afd-66cfea7c158f", "type": "concept", "title": "Replication files"}], "description": "Reproducible workflow makes analysis inspectable, rerunnable, and easier to improve."}, {"id": "982e263c-44f2-4084-a517-950d351cceed", "type": "subtopic", "title": "Data documentation", "children": [{"id": "c751c098-490f-414e-961b-b70662188461", "type": "concept", "title": "Codebooks"}, {"id": "8cac2a57-76ef-4a43-bacb-50f86a695f96", "type": "concept", "title": "Metadata"}, {"id": "d6248f1b-00f1-4f7b-ae9c-6766f8ed9a33", "type": "concept", "title": "Data dictionaries"}, {"id": "3fd4f1cd-ef89-4e98-8e58-d26ca8cc0142", "type": "concept", "title": "Research logs"}], "description": "Good documentation lets others understand what was measured, how, and why."}]}, {"id": "03ab1727-58a2-4397-976c-212f235d245d", "type": "topic", "title": "Qualitative Case Studies and Comparative Methods", "description": "Use case selection and comparison to build, refine, and test theories about politics.", "children": [{"id": "6f4b217c-6b7b-47f6-98cf-7978accd4fc5", "type": "subtopic", "title": "Case study logic", "children": [{"id": "e7ac7c58-7f41-4848-aea0-dc3f60cd33b4", "type": "concept", "title": "Typical cases"}, {"id": "dde80ceb-3673-415b-9371-0cfa5ab825d5", "type": "concept", "title": "Deviant cases"}, {"id": "87dabddb-3a5c-4ef4-9445-69ed7abbfa33", "type": "concept", "title": "Critical cases"}, {"id": "3b243716-da6e-4a6e-8fe6-7b9b949b5044", "type": "concept", "title": "Most-likely and least-likely cases"}], "description": "Case studies provide depth, context, and leverage on mechanisms that large-N designs may miss."}, {"id": "08445871-0f90-4ea2-869c-2d14746781ab", "type": "subtopic", "title": "Comparative methods", "children": [{"id": "79b9b55f-1915-4b34-a783-7f222a9bcbd7", "type": "concept", "title": "Most similar systems"}, {"id": "f02f318d-0c29-48ae-92bf-ef13f6640554", "type": "concept", "title": "Most different systems"}, {"id": "bd668a0e-0258-4e53-82f5-759512f115f9", "type": "concept", "title": "Small-N comparison"}, {"id": "10c251a3-c472-44f5-aab5-5f9584ea7570", "type": "concept", "title": "Controlled comparison"}], "description": "Comparative designs use structured comparison to identify patterns and rival explanations."}, {"id": "7744703e-bdf0-443e-9b97-71b22af3c712", "type": "subtopic", "title": "Case selection", "children": [{"id": "b9be2e38-7bd1-42c0-96d7-70ab0c30cfa5", "type": "concept", "title": "Selection on outcome"}, {"id": "0386ea0d-90c4-4d6a-ae9d-d0ca0ea62ec6", "type": "concept", "title": "Scope conditions"}, {"id": "29287467-4231-4819-b479-a3231c7aa9cb", "type": "concept", "title": "Negative cases"}, {"id": "3e0e3997-c77f-41c0-8a01-6f3d5df04a68", "type": "concept", "title": "Generalizability"}], "description": "Case selection is a design choice that affects what can be learned."}]}, {"id": "fdc1e1e6-8b5d-4932-922d-5ed01ccdc879", "type": "topic", "title": "Process Tracing and Qualitative Causal Inference", "description": "Analyze causal mechanisms through sequences, evidence tests, documents, interviews, and within-case inference.", "children": [{"id": "9d819983-4455-4037-ba23-4c1bb5f3becb", "type": "subtopic", "title": "Causal mechanisms", "children": [{"id": "53e55e3f-02e2-4532-9c20-b53ff165e707", "type": "concept", "title": "Mechanism"}, {"id": "cf37163e-94b9-49da-8455-a8393b206bbb", "type": "concept", "title": "Sequence"}, {"id": "62d9c918-0730-4231-9bc5-6a1e0bb2b054", "type": "concept", "title": "Timing"}, {"id": "023fc1b5-7584-456b-9c1d-7c972bf6584e", "type": "concept", "title": "Causal process observations"}], "description": "Process tracing examines how a cause produced an outcome through intervening steps."}, {"id": "046ceda7-c060-4ea1-aeb4-c93eaf4839cc", "type": "subtopic", "title": "Evidence tests", "children": [{"id": "98dbd926-e28d-4d1c-aceb-e9f405b3cb63", "type": "concept", "title": "Hoop tests"}, {"id": "37272e23-47b7-4bef-abae-1a645c0a2b6c", "type": "concept", "title": "Smoking-gun tests"}, {"id": "12684345-a3b8-4e2e-9d17-79a91b3b1f27", "type": "concept", "title": "Straw-in-the-wind tests"}, {"id": "0fd3d8ff-9fd0-445b-9af6-77323d50940a", "type": "concept", "title": "Doubly decisive tests"}], "description": "Evidence tests help students weigh whether a piece of evidence supports or weakens a causal story."}, {"id": "d2c2223d-f594-47ac-9fdd-e879f0acf0f1", "type": "subtopic", "title": "Sources and triangulation", "children": [{"id": "b69545de-af46-4d48-9ae6-47124d9f5efe", "type": "concept", "title": "Archives"}, {"id": "48179037-981c-40ce-b75d-72546e586476", "type": "concept", "title": "Elite interviews"}, {"id": "44a745e5-f0aa-41bc-a330-6d9c90ce8ac9", "type": "concept", "title": "Media records"}, {"id": "88c0bf4d-9ac5-4588-8044-f6b7c9b8a6a9", "type": "concept", "title": "Official documents"}], "description": "Strong process tracing uses multiple sources to reduce overreliance on any single account."}]}, {"id": "f1dd349f-3a59-4625-a997-6f1976baadc3", "type": "topic", "title": "Interviews, Fieldwork, Ethnography, and Elite Research", "description": "Collect qualitative evidence ethically through interviews, observation, fieldnotes, and context-sensitive fieldwork.", "children": [{"id": "60a51f8e-072f-46c8-8880-cc5aa976cb60", "type": "subtopic", "title": "Interview design", "children": [{"id": "218171b3-3600-44d6-b2ba-276e70f7c75c", "type": "concept", "title": "Interview protocols"}, {"id": "1346251a-0698-466a-84f9-8f145238943b", "type": "concept", "title": "Sampling respondents"}, {"id": "bd7f0aa5-de26-4e94-b9c4-9484abab19dc", "type": "concept", "title": "Elite interviews"}, {"id": "539bc5c5-80df-420c-ae91-9aea64b881ac", "type": "concept", "title": "Probing and follow-up"}], "description": "Interviews can reveal beliefs, strategies, interpretations, and hidden processes."}, {"id": "96bbb55f-5f93-4a8b-a54f-5bdc0ff483c9", "type": "subtopic", "title": "Fieldwork and ethnography", "children": [{"id": "429ead4e-2d83-438f-b443-9d5d35bd1a50", "type": "concept", "title": "Participant observation"}, {"id": "3ef7bf82-79af-4d52-add8-5652defb0e6a", "type": "concept", "title": "Fieldnotes"}, {"id": "7e2ed2b5-7803-41c3-ab8a-b6be01d23d53", "type": "concept", "title": "Positionality"}, {"id": "9d65fb4a-d07c-4eb1-9bbf-705201ad2866", "type": "concept", "title": "Access and trust"}], "description": "Fieldwork helps researchers understand political life in context and notice what surveys may miss."}, {"id": "23863543-d03a-44fd-933b-13948059f830", "type": "subtopic", "title": "Qualitative data management", "children": [{"id": "54cb4de2-f99e-4ee1-a4dc-f8182445a321", "type": "concept", "title": "Transcription"}, {"id": "1c65c8b4-1294-4511-b366-1d3147a0b87f", "type": "concept", "title": "Coding"}, {"id": "5e539649-4a9f-4a9b-8e07-5779a877e88d", "type": "concept", "title": "Memoing"}, {"id": "4bce8339-abbd-4d04-8608-8c8001e898e5", "type": "concept", "title": "Confidentiality protections"}], "description": "Qualitative evidence needs systematic organization and transparent analysis."}]}, {"id": "30d2ffbf-a7bb-4159-80d4-a51edb7a3ef2", "type": "topic", "title": "Survey Design, Public Opinion, Sampling, and Weighting", "description": "Design and evaluate surveys that measure political attitudes, behavior, identity, and preferences.", "children": [{"id": "0703af0a-f868-4fd1-b1da-2d1cce1e9211", "type": "subtopic", "title": "Questionnaire design", "children": [{"id": "b955e9e7-561a-4c28-8d5f-5d6035e15c6d", "type": "concept", "title": "Question wording"}, {"id": "ea6301d4-9b0e-42a5-a46f-0f4d8572159f", "type": "concept", "title": "Response options"}, {"id": "3ee42f1c-0555-4d3a-910e-e0b06f0ab59a", "type": "concept", "title": "Question order"}, {"id": "8dc9d581-4205-4578-9fdc-769ea93f1a70", "type": "concept", "title": "Pretesting"}], "description": "Survey questions must measure attitudes or behaviors without leading, confusing, or excluding respondents."}, {"id": "5ab2b575-963a-4a71-9d3d-da0143af60d4", "type": "subtopic", "title": "Sampling", "children": [{"id": "b66ceb21-3baf-4136-bec1-ea8c3696aa5f", "type": "concept", "title": "Probability sampling"}, {"id": "9003212f-9450-4b54-8402-9e31140938d6", "type": "concept", "title": "Nonprobability samples"}, {"id": "2ae8e8e0-d1f8-48b4-9285-0385e5c97a05", "type": "concept", "title": "Sampling frames"}, {"id": "e9fdb24f-afb7-4ead-ac6e-2c72f5f94330", "type": "concept", "title": "Nonresponse"}], "description": "Sampling determines whose voices are represented and how much uncertainty surrounds estimates."}, {"id": "f5d34fac-e5ca-4c3b-b688-08404de77989", "type": "subtopic", "title": "Weighting and interpretation", "children": [{"id": "f76981f2-9311-4087-9ca5-b937064eef83", "type": "concept", "title": "Post-stratification"}, {"id": "3ffd03ab-dde0-46b2-96b3-de90db874075", "type": "concept", "title": "Margins of error"}, {"id": "88f2d010-ddcf-4247-bc69-3221180106ef", "type": "concept", "title": "Design effects"}, {"id": "964cde32-c3e7-44cc-a560-64360431fd5e", "type": "concept", "title": "Transparency reports"}], "description": "Weighting helps align survey samples with target populations but cannot fix every design flaw."}]}, {"id": "5e8d9942-b350-4a8d-8498-5588178c7de5", "type": "topic", "title": "Experiments, Natural Experiments, and Causal Identification", "description": "Study randomized and quasi-experimental approaches for estimating political and policy effects.", "children": [{"id": "695a97cc-6abf-4d4f-b3a9-6ccbf7da375e", "type": "subtopic", "title": "Randomized experiments", "children": [{"id": "0eeb6d10-df1f-4eb6-9c54-52f17bcd72be", "type": "concept", "title": "Treatment assignment"}, {"id": "5cc7736d-7c53-4615-bff3-76156495de99", "type": "concept", "title": "Control groups"}, {"id": "4396a3bc-62bd-4cdc-8a35-26201a50b347", "type": "concept", "title": "Field experiments"}, {"id": "ae1cd7a4-f59b-413d-8e60-2acfd1944dfa", "type": "concept", "title": "Survey experiments"}], "description": "Experiments use random assignment to improve causal inference when ethical and feasible."}, {"id": "0d5b2ef4-eeb8-4759-8a97-5a06486cb3e5", "type": "subtopic", "title": "Natural experiments", "children": [{"id": "d4ddb906-8b61-4c44-9666-92ea1834d1ca", "type": "concept", "title": "As-if random assignment"}, {"id": "7db04bc6-4299-4d61-8a03-153b4839b087", "type": "concept", "title": "Policy shocks"}, {"id": "f378242f-b7f5-44bf-9688-1d8e89a43676", "type": "concept", "title": "Regression discontinuity"}, {"id": "9b049daf-8fe2-4aa8-bbfd-d13e1ab141f2", "type": "concept", "title": "Instrumental variables overview"}], "description": "Natural experiments exploit political or institutional variation that approximates random assignment."}, {"id": "35a6a4bf-80b4-48f7-a5fc-801d2a2a0e8a", "type": "subtopic", "title": "Difference-in-differences and matching", "children": [{"id": "f3505d03-9236-428d-be31-4346809e6f13", "type": "concept", "title": "Parallel trends"}, {"id": "c8cbf893-90fc-4e05-9d6b-283cb6e15eee", "type": "concept", "title": "Matched comparisons"}, {"id": "1112ea79-8248-4a57-b49e-4b1a16a886cd", "type": "concept", "title": "Panel data"}, {"id": "ff72fa83-b253-4d04-869a-a2236c5ba9cc", "type": "concept", "title": "Sensitivity checks"}], "description": "Quasi-experimental designs compare changes or comparable units to estimate effects."}]}, {"id": "1f86d6d4-8cf6-4a28-8c5f-1634d9a09910", "type": "topic", "title": "Regression, Statistical Control, and Model Interpretation", "description": "Use regression-based analysis responsibly to describe relationships, test hypotheses, and communicate uncertainty.", "children": [{"id": "b3aebe24-0027-40c9-8f69-60af4ac17dfb", "type": "subtopic", "title": "Regression foundations", "children": [{"id": "0416cbfe-3113-4b1f-b1d3-dfa8a9841f0b", "type": "concept", "title": "Bivariate regression"}, {"id": "cbdfdcd1-d803-4000-8518-3d445f7055b2", "type": "concept", "title": "Multiple regression"}, {"id": "80d46508-f397-404a-879d-a2fc423aec7e", "type": "concept", "title": "Logistic regression awareness"}, {"id": "a3807102-d182-4758-8cfd-fc54d8baccdc", "type": "concept", "title": "Fixed effects awareness"}], "description": "Regression helps summarize relationships while controlling for observed variables."}, {"id": "0648d072-a08d-45c1-9694-f9e840d53d7e", "type": "subtopic", "title": "Model assumptions", "children": [{"id": "ea3599a6-94e7-456c-a0b6-afb5acdc5a07", "type": "concept", "title": "Linearity"}, {"id": "a45d1193-d61a-458d-9da4-15dc8088d4fc", "type": "concept", "title": "Independence"}, {"id": "4cce464a-97d6-456a-a67f-6d54c6cd2d66", "type": "concept", "title": "Collinearity"}, {"id": "eab01a7a-e55d-48e8-a62c-caa1fe46a028", "type": "concept", "title": "Functional form"}], "description": "Students learn that models are arguments with assumptions, not automatic truth machines."}, {"id": "b0db04c1-87fa-4014-b11a-cef133dfea82", "type": "subtopic", "title": "Interpreting results", "children": [{"id": "633652a5-15a2-4ae6-b1f6-f86c1d3352b8", "type": "concept", "title": "Coefficients"}, {"id": "faefca0f-c754-4acc-9b37-dce0587f9c18", "type": "concept", "title": "Confidence intervals"}, {"id": "d03d4ffa-d1b7-4166-9150-51265b99bb01", "type": "concept", "title": "Predicted values"}, {"id": "8a6ca30a-24c2-48c2-98ad-3ed146e236b9", "type": "concept", "title": "Robustness checks"}], "description": "Interpretation emphasizes substantive meaning, uncertainty, and limitations."}]}, {"id": "768bf64f-5db1-44af-89cb-d18b7142c9cd", "type": "topic", "title": "Content Analysis, Text-as-Data, and Computational Political Analysis", "description": "Analyze speeches, manifestos, social media, news, laws, and other political texts with qualitative and computational tools.", "children": [{"id": "503015d1-d247-4ffd-a274-2ce4854b081a", "type": "subtopic", "title": "Manual content analysis", "children": [{"id": "6257e583-46d7-4e79-8786-64a27e145a23", "type": "concept", "title": "Coding scheme"}, {"id": "07bed6e1-6779-4c72-b650-49f968a605b3", "type": "concept", "title": "Intercoder reliability"}, {"id": "f789f81d-2ff7-4716-8aae-ab885805f264", "type": "concept", "title": "Manifest and latent content"}, {"id": "e208cf3e-1634-4d9c-a6f0-13447dd15c61", "type": "concept", "title": "Sampling texts"}], "description": "Manual coding helps students analyze political communication systematically."}, {"id": "0ec01e0a-aa24-4a84-ac58-7608fc2098ac", "type": "subtopic", "title": "Text-as-data", "children": [{"id": "24af14cc-f618-4498-84a6-75323db041dd", "type": "concept", "title": "Tokenization"}, {"id": "7afe787a-7770-4111-8ff0-e34e37d04632", "type": "concept", "title": "Dictionary methods"}, {"id": "6a9fe8cd-486d-4838-acab-2a7b26f0d4b6", "type": "concept", "title": "Topic models"}, {"id": "39d54ca4-6240-443d-97f5-fd5a93f2358a", "type": "concept", "title": "Sentiment and framing"}], "description": "Computational text analysis expands the scale of political communication research."}, {"id": "7bb93cf3-afde-470b-bdc2-f31574e9736f", "type": "subtopic", "title": "Computational cautions", "children": [{"id": "b796b87a-ffe0-4d4f-826d-5f8cf8e5c2be", "type": "concept", "title": "Preprocessing choices"}, {"id": "d9957854-0cb5-403e-ba99-09aff74bb9eb", "type": "concept", "title": "Bias in corpora"}, {"id": "3cf9383d-1ac2-4e6d-89d0-e4db9dbb84cc", "type": "concept", "title": "Model validation"}, {"id": "6e57a7b5-2dd1-4a05-93a0-da04824383cd", "type": "concept", "title": "Ethical use of scraped data"}], "description": "Text models require validation, transparency, and careful interpretation."}]}, {"id": "622102f7-af0d-4186-a700-ad5ff81cbad6", "type": "topic", "title": "Mixed Methods, Triangulation, and Research Integration", "description": "Combine qualitative and quantitative evidence so designs answer richer questions than any one method can alone.", "children": [{"id": "3e4c6fb4-2165-4755-9051-347e3d17f73c", "type": "subtopic", "title": "Why mix methods", "children": [{"id": "951c098f-ca0f-4591-97c4-5f5c8e3402dc", "type": "concept", "title": "Complementarity"}, {"id": "4b037fda-73f3-47f2-8501-83146c2ebb91", "type": "concept", "title": "Triangulation"}, {"id": "84a283f9-6274-4b53-90fd-4ac3a997c880", "type": "concept", "title": "Developmental sequencing"}, {"id": "5ff9b3bc-650f-4863-baeb-0b4a04ae7b58", "type": "concept", "title": "Expansion"}], "description": "Mixed methods combine breadth, depth, mechanism, and measurement in one design."}, {"id": "379e46c8-eed0-4e0f-97bb-940b283ed3f8", "type": "subtopic", "title": "Mixed-methods designs", "children": [{"id": "6a63f8cc-1e77-4aab-a6f3-465a479e9b9b", "type": "concept", "title": "Sequential explanatory"}, {"id": "303fbdcd-52d2-4e98-990a-c8ba00b9fba8", "type": "concept", "title": "Sequential exploratory"}, {"id": "08be4949-120c-4857-a0f9-3cc2e09070b3", "type": "concept", "title": "Convergent design"}, {"id": "f879eda3-453c-40ae-bda4-f309d938a030", "type": "concept", "title": "Nested analysis"}], "description": "Students learn design structures for integrating qualitative and quantitative evidence."}, {"id": "6e9f82f9-3c02-4e71-b27c-3c58ce0b198a", "type": "subtopic", "title": "Integration", "children": [{"id": "285f6718-bfb6-4395-8d62-922f94538e65", "type": "concept", "title": "Joint displays"}, {"id": "db961785-4329-4bbe-8f2d-6bf4ddd7e327", "type": "concept", "title": "Case selection from large-N results"}, {"id": "4cd1820c-23c3-44e7-ac6d-239ec5d447f1", "type": "concept", "title": "Mechanism testing"}, {"id": "9794786d-b720-41eb-a141-a3f50e9093b3", "type": "concept", "title": "Reconciling contradictions"}], "description": "Integration is the point where evidence types speak to each other rather than sit in separate chapters."}]}, {"id": "08c67b06-507e-482a-973f-d4266b36fef6", "type": "topic", "title": "Ethics, Human Subjects, Data Responsibility, and Open Science", "description": "Protect participants, communities, and democratic integrity while using transparent and reproducible research practices.", "children": [{"id": "2351df83-2ec9-40f4-bdba-f55b139a899e", "type": "subtopic", "title": "Human subjects ethics", "children": [{"id": "47c9848e-5ff6-4d47-91bc-b781342eaa62", "type": "concept", "title": "Informed consent"}, {"id": "3b253700-3784-42a7-a19e-76302a5b8efd", "type": "concept", "title": "Confidentiality"}, {"id": "f0d2b5fe-a1c7-4f3c-b88f-f08e6ae60a78", "type": "concept", "title": "IRB review"}, {"id": "c831ffc8-d407-4d32-80af-25f1949425f1", "type": "concept", "title": "Risk minimization"}], "description": "Political research can expose people to social, legal, physical, or political risk."}, {"id": "29000a64-a02f-4f31-aada-4d43d628e790", "type": "subtopic", "title": "Data responsibility", "children": [{"id": "4409724d-04d5-44cb-a5c6-0d1a5992344b", "type": "concept", "title": "De-identification"}, {"id": "aaf5ea73-a86f-4a8b-838a-88f193f7454c", "type": "concept", "title": "Data security"}, {"id": "c88b7197-bb60-4468-8d7e-1bb1d1383faa", "type": "concept", "title": "Vulnerable populations"}, {"id": "fe0fe6d1-2c1c-472d-9977-48635d1e7d65", "type": "concept", "title": "Authoritarian and conflict settings"}], "description": "Researchers must treat sensitive political data with care."}, {"id": "4a9a889f-ea6f-4ce8-ad03-3dff78ff7cd3", "type": "subtopic", "title": "Open science and transparency", "children": [{"id": "a9a98c50-ec75-42c5-ac90-1edf4a4bdff9", "type": "concept", "title": "Preregistration"}, {"id": "158f81e4-a26f-4fac-95bc-1e79834ca358", "type": "concept", "title": "Replication packages"}, {"id": "cd049ba8-6f87-4cee-a163-6fcbc5ee1b70", "type": "concept", "title": "Qualitative transparency"}, {"id": "fc04ade9-2257-44e7-9def-61bf4ea0802a", "type": "concept", "title": "Research integrity"}], "description": "Transparency improves trust, critique, and cumulative knowledge."}]}, {"id": "cab34918-5fd4-434d-be30-b332cc933a38", "type": "topic", "title": "Research Proposal, Replication, Visualization, and Scholarly Communication", "description": "Synthesize the course through a proposal or replication portfolio with clear design, evidence, analysis, and communication.", "children": [{"id": "b41c31c4-ff5e-439e-a055-99499d71657b", "type": "subtopic", "title": "Research proposal", "children": [{"id": "f30bda38-013c-4cc1-901e-e893bb815623", "type": "concept", "title": "Research question"}, {"id": "83de0de9-fc5c-4450-8875-4f615c01e33e", "type": "concept", "title": "Theory and hypotheses"}, {"id": "0a20a82d-89f0-4bb5-85cb-762d9590af59", "type": "concept", "title": "Methods section"}, {"id": "fb2c3a1c-791d-4012-ba58-9b6292846a5d", "type": "concept", "title": "Limitations"}], "description": "The proposal is where students assemble question, theory, design, data, method, ethics, and contribution."}, {"id": "002fabec-d8c1-4fe1-96ac-4a661d01eab8", "type": "subtopic", "title": "Replication and robustness", "children": [{"id": "99f1bcb9-f3c3-47d0-ad5c-fc925f8e0d6a", "type": "concept", "title": "Reproducing tables"}, {"id": "77057dfe-b4d1-487c-a965-5807e60a4735", "type": "concept", "title": "Alternative specifications"}, {"id": "ceea7d8e-bc1c-4c5f-9163-81f6bd2bde41", "type": "concept", "title": "Code review"}, {"id": "8641ea9a-2204-4b1b-a5f8-9c2e3d5eb8cb", "type": "concept", "title": "Robustness checks"}], "description": "Replication teaches students to verify claims and understand analytic choices."}, {"id": "7917f574-6b05-448b-b9b7-a2d5789b0e92", "type": "subtopic", "title": "Communication", "children": [{"id": "2f526eac-bbbb-4874-8e73-0e84b5fae570", "type": "concept", "title": "Data visualization"}, {"id": "b4a846ac-e9f3-49c4-bd61-27da63243aa1", "type": "concept", "title": "Research poster"}, {"id": "b4eae6e8-7b40-4fa3-8f8f-936850ba2408", "type": "concept", "title": "Policy 